(() => {
  'use strict';

  const Festacol = window.Festacol;
  if (!Festacol) throw new Error('Festacol shared runtime is unavailable.');
  const { store: Store, questions: Questions, assessment: Engine, proctor: Proctor, qr: QR, utils } = Festacol;
  const app = document.getElementById('app');
  if (!app) throw new Error('Festacol canonical shell is unavailable.');

  const esc = (value) => String(value ?? '')
    .replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;').replaceAll("'", '&#039;');

  // Paths verified against themesberg/flowbite-icons.
  const ICONS = Object.freeze({
    home: ['M4 12l8-8 8 8M6 10.5V19a1 1 0 0 0 1 1h3v-3a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1v3h3a1 1 0 0 0 1-1v-8.5'],
    users: ['M4.5 17H4a1 1 0 0 1-1-1 3 3 0 0 1 3-3h1m0-3.05A2.5 2.5 0 1 1 9 5.5M19.5 17h.5a1 1 0 0 0 1-1 3 3 0 0 0-3-3h-1m0-3.05a2.5 2.5 0 1 0-2-4.45m.5 13.5h-7a1 1 0 0 1-1-1 3 3 0 0 1 3-3h3a3 3 0 0 1 3 3 1 1 0 0 1-1 1Zm-1-9.5a2.5 2.5 0 1 1-5 0 2.5 2.5 0 0 1 5 0Z'],
    staff: ['M10 19H5a1 1 0 0 1-1-1v-1a3 3 0 0 1 3-3h2m10 1a3 3 0 0 1-3 3m3-3a3 3 0 0 0-3-3m3 3h1m-4 3a3 3 0 0 1-3-3m3 3v1m-3-4a3 3 0 0 1 3-3m-3 3h-1m4-3v-1m-2.121 1.879-.707-.707m5.656 5.656-.707-.707m-4.242 0-.707.707m5.656-5.656-.707.707M12 8a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z'],
    book: ['M12.1429 11v9m0-9c-2.50543-.7107-3.19099-1.39543-6.13657-1.34968-.48057.00746-.86348.38718-.86348.84968v7.2884c0 .4824.41455.8682.91584.8617 2.77491-.0362 3.45995.6561 6.08421 1.3499m0-9c2.5053-.7107 3.1067-1.39542 6.0523-1.34968.4806.00746.9477.38718.9477.84968v7.2884c0 .4824-.4988.8682-1 .8617-2.775-.0362-3.3758.6561-6 1.3499m2-14c0 1.10457-.8955 2-2 2-1.1046 0-2-.89543-2-2s.8954-2 2-2c1.1045 0 2 .89543 2 2Z'],
    school: ['M8 20v-9l-4 1.125V20h4Zm0 0h8m-8 0V6.66667M16 20v-9l4 1.125V20h-4Zm0 0V6.66667M18 8l-6-4-6 4m5 1h2m-2 3h2'],
    chart: ['M10 6.025A7.5 7.5 0 1 0 17.975 14H10V6.025Z','M13.5 3c-.169 0-.334.014-.5.025V11h7.975c.011-.166.025-.331.025-.5A7.5 7.5 0 0 0 13.5 3Z'],
    cog: ['M21 13v-2a1 1 0 0 0-1-1h-.757l-.707-1.707.535-.536a1 1 0 0 0 0-1.414l-1.414-1.414a1 1 0 0 0-1.414 0l-.536.535L14 4.757V4a1 1 0 0 0-1-1h-2a1 1 0 0 0-1 1v.757l-1.707.707-.536-.535a1 1 0 0 0-1.414 0L4.929 6.343a1 1 0 0 0 0 1.414l.536.536L4.757 10H4a1 1 0 0 0-1 1v2a1 1 0 0 0 1 1h.757l.707 1.707-.535.536a1 1 0 0 0 0 1.414l1.414 1.414a1 1 0 0 0 1.414 0l.536-.535 1.707.707V20a1 1 0 0 0 1 1h2a1 1 0 0 0 1-1v-.757l1.707-.708.536.536a1 1 0 0 0 1.414 0l1.414-1.414a1 1 0 0 0 0-1.414l-.535-.536.707-1.707H20a1 1 0 0 0 1-1Z','M12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6Z'],
    bell: ['M12 5.365V3m0 2.365a5.338 5.338 0 0 1 5.133 5.368v1.8c0 2.386 1.867 2.982 1.867 4.175 0 .593 0 1.292-.538 1.292H5.538C5 18 5 17.301 5 16.708c0-1.193 1.867-1.789 1.867-4.175v-1.8A5.338 5.338 0 0 1 12 5.365ZM8.733 18c.094.852.306 1.54.944 2.112a3.48 3.48 0 0 0 4.646 0c.638-.572 1.236-1.26 1.33-2.112h-6.92Z'],
    search: ['m21 21-3.5-3.5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z'],
    menu: ['M5 7h14M5 12h14M5 17h14'],
    close: ['M6 18 17.94 6M18 18 6.06 6'],
    more: ['M6 12h.01m6 0h.01m5.99 0h.01']
  });
  const ICON_STROKE_WIDTH = Object.freeze({ more: 3 });
  const icon = (name, cls = 'size-5 shrink-0') => `<svg class="${cls}" viewBox="0 0 24 24" fill="none" aria-hidden="true">${(ICONS[name] || ICONS.book).map((path) => `<path d="${path}" stroke="currentColor" stroke-width="${ICON_STROKE_WIDTH[name] || 2}" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}</svg>`;

  const ROUTES = Object.freeze([
    { key: 'overview', label: 'Overview', icon: 'home' },
    { key: 'students', label: 'Students', icon: 'users' },
    { key: 'staff', label: 'Staff', icon: 'staff' },
    { key: 'exams', label: 'Examinations', icon: 'book' },
    { key: 'classes', label: 'Classes', icon: 'school' },
    { key: 'questions', label: 'Question Bank', icon: 'book' },
    { key: 'reports', label: 'Reports', icon: 'chart' },
    { key: 'settings', label: 'Settings', icon: 'cog' }
  ]);
  const ROUTE_MAP = Object.fromEntries(ROUTES.map((route) => [route.key, route.label]));
  const RECORD_KEYS = ['student', 'staff', 'exam', 'class', 'question', 'attempt'];
  const OVERLAY_KEYS = ['modal', 'step', ...RECORD_KEYS];
  const ALLOWED_QUERY_KEYS = new Set(['route','page','view','tab','modal','step','student','staff','exam','class','question','attempt','q','status','level','pathway','subject','type','difficulty','source','role']);
  const MODES = Object.freeze({ qualifier:'Placement qualifier', mixed:'Mixed subjects', single:'Single subject', waec:'WAEC practice' });
  const btnPrimary = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg bg-black px-4 py-2 text-sm font-semibold text-white transition hover:bg-neutral-800 focus:outline-none focus:ring-4 focus:ring-neutral-300 disabled:cursor-not-allowed disabled:opacity-40';
  const btnSecondary = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg border border-neutral-300 bg-white px-4 py-2 text-sm font-semibold text-neutral-900 transition hover:bg-neutral-100 focus:outline-none focus:ring-4 focus:ring-neutral-200 disabled:cursor-not-allowed disabled:opacity-40';
  const btnDanger = 'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg bg-red-700 px-4 py-2 text-sm font-semibold text-white transition hover:bg-red-800 focus:outline-none focus:ring-4 focus:ring-red-200 disabled:cursor-not-allowed disabled:opacity-40';
  const iconBtn = 'inline-flex size-10 items-center justify-center rounded-lg border border-neutral-300 bg-white text-neutral-700 transition hover:bg-neutral-100 hover:text-black focus:outline-none focus:ring-4 focus:ring-neutral-200';
  const field = 'block min-h-11 w-full rounded-lg border border-neutral-300 bg-white px-3 py-2.5 text-sm text-neutral-950 placeholder:text-neutral-400 focus:border-black focus:ring-black';
  const label = 'text-sm font-semibold text-neutral-800';
  const card = 'rounded-2xl border border-neutral-200 bg-white shadow-sm';

  let data = null;
  let userHashes = new Map();
  let wizard = null;
  let lastFocus = null;
  let adminModal = null;
  let mobileDrawer = null;
  let suppressModalUrlClose = false;

  const params = () => new URL(location.href).searchParams;
  const currentPage = () => ROUTE_MAP[params().get('page')] ? params().get('page') : 'overview';
  const canonicalUrl = (next = {}) => {
    const current = params();
    const merged = {};
    for (const [key, value] of current.entries()) if (ALLOWED_QUERY_KEYS.has(key) && key !== 'route') merged[key] = value;
    for (const [key, value] of Object.entries(next)) {
      if (value === undefined || value === null || value === '') delete merged[key]; else merged[key] = String(value);
    }
    return utils.routeUrl('admin', merged, location.href);
  };
  const href = (page, extra = {}) => utils.routeUrl('admin', { page, ...extra }, location.href);
  const clearOverlay = (target) => { for (const key of OVERLAY_KEYS) delete target[key]; };
  const navigate = (page, extra = {}, replace = false) => {
    const target = { page };
    clearOverlay(target);
    Object.assign(target, extra);
    history[replace ? 'replaceState' : 'pushState']({}, '', utils.routeUrl('admin', target, location.href));
    render();
  };
  const patchUrl = (changes, { replace = false, renderNow = true } = {}) => {
    const url = canonicalUrl(changes);
    history[replace ? 'replaceState' : 'pushState']({}, '', url);
    if (renderNow) render();
  };
  const openRecord = (kind, value, page = currentPage(), extra = {}) => {
    const changes = { page, modal: kind, ...extra };
    for (const key of RECORD_KEYS) changes[key] = key === kind ? value : null;
    patchUrl(changes);
  };
  const closeOverlayUrl = ({ replace = false } = {}) => {
    const changes = {};
    for (const key of OVERLAY_KEYS) changes[key] = null;
    patchUrl(changes, { replace });
  };
  const normalizeLocation = () => {
    const current = params();
    const changes = {};
    let changed = false;
    if (current.get('route') !== 'admin') { changes.route = 'admin'; changed = true; }
    if (current.get('page') === 'users') { changes.page = 'students'; changed = true; }
    if (current.has('classId') && !current.has('class')) { changes.class = current.get('classId'); changes.classId = null; changed = true; }
    if (!ROUTE_MAP[current.get('page')]) { changes.page = 'overview'; changed = true; }
    if (changed) {
      const url = new URL(location.href);
      url.searchParams.set('route', 'admin');
      Object.entries(changes).forEach(([key, value]) => value === null ? url.searchParams.delete(key) : url.searchParams.set(key, value));
      history.replaceState({}, '', url.href);
    }
  };

  const sessionState = (session) => {
    if (!session) return 'missing';
    const now = Date.now();
    if (session.status !== 'open') return session.status;
    if (session.startsAt && now < Number(session.startsAt)) return 'scheduled';
    if (session.endsAt && now >= Number(session.endsAt)) return 'closed';
    return 'open';
  };
  const formatDate = (timestamp) => timestamp ? new Intl.DateTimeFormat('en-NG',{dateStyle:'medium',timeStyle:'short'}).format(new Date(timestamp)) : 'Not scheduled';
  const coverage = (session) => session.mode === 'qualifier' ? 'Placement domains' : session.subjects.map((code) => Questions.subjectByCode(data, code)?.label || code).join(', ');
  const tone = (status) => ['open','active','submitted','on-track'].includes(status) ? 'emerald' : ['scheduled'].includes(status) ? 'blue' : ['draft','review','in-progress'].includes(status) ? 'amber' : ['closed','inactive','graduating'].includes(status) ? 'neutral' : 'red';
  const badge = (text, explicitTone = tone(String(text).toLowerCase())) => `<span class="inline-flex items-center rounded-full border px-2.5 py-1 text-xs font-semibold ${explicitTone === 'emerald' ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : explicitTone === 'amber' ? 'border-amber-200 bg-amber-50 text-amber-800' : explicitTone === 'red' ? 'border-red-200 bg-red-50 text-red-800' : explicitTone === 'blue' ? 'border-blue-200 bg-blue-50 text-blue-800' : 'border-neutral-200 bg-neutral-100 text-neutral-700'}">${esc(text)}</span>`;
  const initials = (name) => String(name || '?').split(/\s+/u).slice(0,2).map((part) => part[0]).join('').toUpperCase();
  const mean = (values) => values.length ? Math.round(values.reduce((sum,value) => sum + (Number(value) || 0), 0) / values.length) : 0;
  const classFor = (classId) => Store.listClasses().find((item) => item.id === classId);
  const pageHead = (eyebrow,title,detail,actions='') => `<div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div class="max-w-3xl"><p class="text-xs font-bold uppercase tracking-[.14em] text-neutral-500">${esc(eyebrow)}</p><h2 class="mt-2 font-display text-2xl font-extrabold tracking-tight sm:text-3xl">${esc(title)}</h2><p class="mt-2 max-w-2xl text-sm leading-6 text-neutral-600">${esc(detail)}</p></div>${actions ? `<div class="flex shrink-0 flex-wrap gap-2">${actions}</div>` : ''}</div>`;
  const empty = (title,detail,action='') => `<div class="grid min-h-56 place-items-center p-7 text-center"><div class="max-w-md"><span class="mx-auto grid size-12 place-items-center rounded-xl bg-neutral-100 text-neutral-500">${icon('book')}</span><h3 class="mt-4 font-display text-lg font-extrabold">${esc(title)}</h3><p class="mt-2 text-sm leading-6 text-neutral-500">${esc(detail)}</p>${action ? `<div class="mt-5">${action}</div>` : ''}</div></div>`;
  const metric = (labelText,value,detail) => `<article class="${card} p-5"><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">${esc(labelText)}</p><strong class="mt-3 block font-display text-3xl font-extrabold tracking-tight">${esc(value)}</strong><p class="mt-2 text-xs leading-5 text-neutral-500">${esc(detail)}</p></article>`;
  const alertMarkup = (message,kind='info') => `<div class="rounded-xl border p-4 text-sm leading-6 ${kind==='danger'?'border-red-200 bg-red-50 text-red-900':kind==='warning'?'border-amber-200 bg-amber-50 text-amber-900':kind==='success'?'border-emerald-200 bg-emerald-50 text-emerald-900':'border-neutral-200 bg-neutral-50 text-neutral-800'}">${esc(message)}</div>`;
  const responsiveTable = (headers, rows, cards) => `<div class="hidden overflow-x-auto md:block"><table class="w-full text-left text-sm"><thead class="border-b border-neutral-200 bg-neutral-50 text-[11px] font-bold uppercase tracking-[.1em] text-neutral-500"><tr>${headers.map((h)=>`<th class="whitespace-nowrap px-4 py-3">${esc(h)}</th>`).join('')}</tr></thead><tbody class="divide-y divide-neutral-100">${rows}</tbody></table></div><div class="divide-y divide-neutral-100 md:hidden">${cards}</div>`;

  function shell() {
    app.innerHTML = `<div class="min-h-screen bg-neutral-50 text-neutral-950">
      <aside class="fixed inset-y-0 left-0 z-30 hidden w-64 border-r border-neutral-200 bg-white lg:flex lg:flex-col">
        <div class="border-b border-neutral-200 px-5 py-5"><a href="${href('overview')}" class="flex items-center gap-3"><span class="grid size-10 place-items-center rounded-xl bg-black font-display text-sm font-black text-white">F</span><span><strong class="block font-display text-base">Festacol</strong><span class="text-xs text-neutral-500">Administration</span></span></a></div>
        <nav id="desktop-nav" class="flex-1 space-y-1 overflow-y-auto p-3" aria-label="Administration"></nav>
        <div class="border-t border-neutral-200 p-4"><p class="text-xs font-semibold text-neutral-500">Prototype workspace</p><p class="mt-1 text-xs leading-5 text-neutral-400">Browser-local academic operations.</p></div>
      </aside>
      <div class="lg:pl-64">
        <header class="sticky top-0 z-20 border-b border-neutral-200 bg-white/95 backdrop-blur-xl">
          <div class="flex min-h-16 items-center gap-3 px-4 sm:px-6 lg:px-8">
            <button id="mobile-nav-button" type="button" class="${iconBtn} lg:hidden" aria-controls="mobile-nav-dialog" aria-label="Open navigation">${icon('menu')}</button>
            <div class="min-w-0 flex-1"><p id="admin-breadcrumb" class="truncate text-[11px] font-bold uppercase tracking-[.12em] text-neutral-400">Administration / Overview</p><p id="admin-page-label" class="truncate text-sm font-bold">Overview</p></div>
            <label class="relative hidden w-full max-w-xs md:block"><span class="sr-only">Search students</span><span class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400">${icon('search','size-4')}</span><input id="admin-global-search" class="${field} pl-9" placeholder="Search students"></label>
            <button id="admin-quick-create" class="${btnPrimary} hidden sm:inline-flex" type="button">Create exam</button>
            <div class="relative"><button id="admin-notifications" data-dropdown-toggle="admin-notification-menu" data-dropdown-placement="bottom-end" class="${iconBtn}" type="button" aria-label="Notifications">${icon('bell')}</button>
              <div id="admin-notification-menu" class="z-40 hidden w-80 rounded-2xl border border-neutral-200 bg-white p-2 shadow-xl" aria-labelledby="admin-notifications"></div>
            </div>
          </div>
        </header>
        <div id="admin-alert" class="hidden"></div>
        <main id="admin-root" tabindex="-1" class="mx-auto max-w-[1600px] px-4 py-6 sm:px-6 lg:px-8"></main>
      </div>
      <aside id="mobile-nav-dialog" class="fixed inset-y-0 left-0 z-50 hidden w-[min(88vw,320px)] -translate-x-full border-r border-neutral-200 bg-white shadow-2xl transition-transform lg:hidden" tabindex="-1" aria-labelledby="mobile-nav-title">
        <div class="flex items-center justify-between border-b border-neutral-200 p-4"><div><strong id="mobile-nav-title" class="font-display">Festacol Admin</strong><p class="text-xs text-neutral-500">Navigation</p></div><button type="button" class="${iconBtn}" data-close-mobile-nav aria-label="Close navigation">${icon('close')}</button></div><nav id="mobile-nav" class="space-y-1 p-3" aria-label="Mobile administration"></nav>
      </aside>
      <div id="mobile-nav-backdrop" class="fixed inset-0 z-40 hidden bg-black/40 backdrop-blur-sm lg:hidden" data-close-mobile-nav></div>
      <div id="admin-dialog" tabindex="-1" aria-hidden="true" class="fixed inset-0 z-[60] hidden h-full max-h-full w-full items-center justify-center overflow-y-auto overflow-x-hidden bg-black/45 p-3 backdrop-blur-sm sm:p-6" role="dialog" aria-modal="true" aria-labelledby="admin-dialog-title">
        <div id="admin-dialog-panel" class="relative max-h-[calc(100vh-1.5rem)] w-full max-w-4xl overflow-y-auto rounded-2xl border border-neutral-200 bg-white shadow-2xl sm:max-h-[calc(100vh-3rem)]"><div id="admin-dialog-content"></div></div>
      </div>
      <div id="toast-stack" class="pointer-events-none fixed bottom-4 right-4 z-[80] grid w-[min(92vw,360px)] gap-2" aria-live="polite"></div>
    </div>`;
    renderNav();
    configureFlowbite();
  }

  const root = () => document.getElementById('admin-root');
  const dialog = () => document.getElementById('admin-dialog');
  const dialogContent = () => document.getElementById('admin-dialog-content');
  const toastStack = () => document.getElementById('toast-stack');
  const announce = (message, kind='danger') => { const host=document.getElementById('admin-alert');host.className='mx-auto max-w-[1600px] px-4 pt-4 sm:px-6 lg:px-8';host.innerHTML=alertMarkup(message,kind); };
  const toast = (message, kind='info') => {
    const node=document.createElement('div');node.className=`pointer-events-auto flex items-start gap-3 rounded-xl border bg-white p-4 shadow-xl ${kind==='danger'?'border-red-200':kind==='success'?'border-emerald-200':'border-neutral-200'}`;
    node.innerHTML=`<div class="min-w-0 flex-1"><strong class="text-sm">${kind==='danger'?'Action needed':kind==='success'?'Updated':'Festacol'}</strong><p class="mt-1 text-xs leading-5 text-neutral-600">${esc(message)}</p></div><button class="rounded-md p-1 hover:bg-neutral-100" data-toast-close aria-label="Dismiss">${icon('close','size-4')}</button>`;
    toastStack().append(node);setTimeout(()=>node.remove(),4500);
  };

  function configureFlowbite() {
    const modalEl=dialog();
    if (window.Modal && modalEl) {
      try { adminModal = new window.Modal(modalEl,{backdrop:'dynamic',closable:true,onHide:()=>{ if(!suppressModalUrlClose && params().get('modal')) closeOverlayUrl(); }}); } catch { adminModal=null; }
    }
    const drawerEl=document.getElementById('mobile-nav-dialog');
    if(window.Drawer && drawerEl){try{mobileDrawer=new window.Drawer(drawerEl,{placement:'left',backdrop:false,bodyScrolling:false});}catch{mobileDrawer=null;}}
    window.initFlowbite?.();
  }
  const showMobileNav=()=>{const el=document.getElementById('mobile-nav-dialog'),back=document.getElementById('mobile-nav-backdrop');mobileDrawer?.show?.();el?.classList.remove('hidden','-translate-x-full');el?.classList.add('translate-x-0');back?.classList.remove('hidden');};
  const hideMobileNav=()=>{const el=document.getElementById('mobile-nav-dialog'),back=document.getElementById('mobile-nav-backdrop');mobileDrawer?.hide?.();el?.classList.add('-translate-x-full');el?.classList.remove('translate-x-0');setTimeout(()=>el?.classList.add('hidden'),150);back?.classList.add('hidden');};

  const openDialog = (content,maxWidth='max-w-4xl') => {
    lastFocus=document.activeElement;
    const panel=document.getElementById('admin-dialog-panel');panel.className=`relative max-h-[calc(100vh-1.5rem)] w-full ${maxWidth} overflow-y-auto rounded-2xl border border-neutral-200 bg-white shadow-2xl sm:max-h-[calc(100vh-3rem)]`;
    dialogContent().innerHTML=content;
    const el=dialog();
    el.classList.remove('hidden');el.classList.add('flex');el.setAttribute('aria-hidden','false');
    adminModal?.show?.();
    queueMicrotask(()=>el.querySelector('button,input,select,textarea,[href]')?.focus());window.initFlowbite?.();
  };
  const hideDialogOnly = () => {
    const el=dialog();if(!el)return;
    suppressModalUrlClose=true;adminModal?.hide?.();suppressModalUrlClose=false;
    el.classList.add('hidden');el.classList.remove('flex');el.setAttribute('aria-hidden','true');dialogContent().innerHTML='';lastFocus?.focus?.();
  };
  const closeDialog = () => params().get('modal') ? closeOverlayUrl() : hideDialogOnly();
  const modalHeader = (eyebrow,title,detail='') => `<div class="sticky top-0 z-10 flex items-start gap-4 border-b border-neutral-200 bg-white/95 px-5 py-4 backdrop-blur-xl sm:px-6"><div class="min-w-0 flex-1"><p class="text-xs font-bold uppercase tracking-[.14em] text-neutral-500">${esc(eyebrow)}</p><h2 id="admin-dialog-title" class="mt-1 font-display text-xl font-extrabold sm:text-2xl">${esc(title)}</h2>${detail?`<p class="mt-1 text-xs leading-5 text-neutral-500">${esc(detail)}</p>`:''}</div><button type="button" class="${iconBtn}" data-close-dialog aria-label="Close dialog">${icon('close')}</button></div>`;
  const confirmDialog = ({title,detail,confirm='Confirm',danger=false,onConfirm}) => {
    openDialog(`${modalHeader('Confirmation',title,detail)}<div class="p-5 sm:p-6">${danger?alertMarkup('This action changes stored academic records. Review the details before continuing.','warning'):''}<div class="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="button" class="${danger?btnDanger:btnPrimary}" data-confirm-action>${esc(confirm)}</button></div></div>`,'max-w-xl');
    dialog().querySelector('[data-confirm-action]').addEventListener('click',async()=>{try{await onConfirm();hideDialogOnly();}catch(error){toast(error.message,'danger');}},{once:true});
  };

  const directExamLink = (session) => Proctor.decorateStudentLink(Store.getSessionLink(session, location.href), Proctor.getAdminPolicy(session.id).cameraRequired);
  const renderQr = (selector,value) => queueMicrotask(()=>{const host=document.querySelector(selector);if(host)QR.render(host,value);});
  const examIdLabel = (session) => `<div class="rounded-xl border border-neutral-200 bg-neutral-50 p-4"><span class="text-[11px] font-bold uppercase tracking-[.14em] text-neutral-500">Exam ID</span><strong class="mt-1 block font-mono text-xl tracking-[.12em] text-neutral-950">${esc(session.id)}</strong><p class="mt-1 text-xs text-neutral-500">Students can enter this ID manually if they cannot scan the QR code.</p></div>`;
  async function hydrateUserHashes(){const entries=await Promise.all(Store.listUsers().filter(u=>u.role==='student').map(async u=>[u.id,await Engine.studentHash(u.firstName,u.lastName)]));userHashes=new Map(entries);}
  const attemptsForUser=(user)=>{const hash=userHashes.get(user.id);return hash?Store.attemptsForStudent(hash):[];};

  function renderNav(){const markup=ROUTES.map(route=>`<a href="${href(route.key)}" data-admin-route="${route.key}" class="flex min-h-11 items-center gap-3 rounded-lg px-3 text-sm font-semibold text-neutral-600 transition hover:bg-neutral-100 hover:text-black focus:outline-none focus:ring-4 focus:ring-neutral-200 aria-[current=page]:bg-black aria-[current=page]:text-white">${icon(route.icon)}<span>${esc(route.label)}</span></a>`).join('');document.getElementById('desktop-nav').innerHTML=markup;document.getElementById('mobile-nav').innerHTML=markup;}
  function chrome(page){document.getElementById('admin-breadcrumb').textContent=`Administration / ${ROUTE_MAP[page]}`;document.getElementById('admin-page-label').textContent=ROUTE_MAP[page];document.querySelectorAll('[data-admin-route]').forEach(link=>link.dataset.adminRoute===page?link.setAttribute('aria-current','page'):link.removeAttribute('aria-current'));renderNotifications();}
  function renderNotifications(){const drafts=Store.listSessions().filter(s=>s.status==='draft'),active=Store.getAttempts().filter(a=>a.startedAt&&!a.submittedAt);const host=document.getElementById('admin-notification-menu');if(!host)return;host.innerHTML=`<div class="px-3 py-2"><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">Activity centre</p><h3 class="mt-1 font-display text-base font-extrabold">Notifications</h3></div><div class="grid gap-2 p-2">${drafts.length?alertMarkup(`${drafts.length} draft exam(s) need publishing or review.`,'warning'):''}${active.length?alertMarkup(`${active.length} attempt(s) are currently in progress.`,'info'):''}${!drafts.length&&!active.length?alertMarkup('No draft exams or active attempts need attention.','success'):''}</div>`;}

  function overviewPage(){const users=Store.listUsers(),classes=Store.listClasses(),sessions=Store.listSessions(),attempts=Store.getAttempts(),students=users.filter(u=>u.role==='student'),active=sessions.filter(s=>sessionState(s)==='open'),submitted=attempts.filter(a=>a.submittedAt&&!a.rewriteArchivedAt),recent=[...attempts].sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)).slice(0,6);root().innerHTML=`${pageHead('Academic operations','Administration overview','A single operating view for students, classes, examination delivery and integrity records.',`<button class="${btnPrimary}" data-open-exam-wizard>Create exam</button>`)}<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Students',students.length,`${students.filter(u=>u.status==='active').length} active records`)}${metric('Classes',classes.filter(c=>c.status==='active').length,'SS1–SS3 academic groups')}${metric('Live exams',active.length,`${sessions.length} configured sessions`)}${metric('Submitted',submitted.length,`${attempts.filter(a=>a.startedAt&&!a.submittedAt).length} currently in progress`)}</section><div class="mt-5 grid gap-5 xl:grid-cols-[1.45fr_.75fr]"><section class="${card} overflow-hidden"><div class="flex items-center justify-between border-b border-neutral-200 px-5 py-4"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">Recent activity</p><h3 class="mt-1 font-display text-lg font-extrabold">Candidate attempts</h3></div><a href="${href('reports',{view:'students'})}" data-admin-link class="${btnSecondary}">Reports</a></div>${recent.length?`<div class="divide-y divide-neutral-100">${recent.map(a=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="grid size-10 shrink-0 place-items-center rounded-xl bg-neutral-100 text-xs font-extrabold">${esc(initials(a.studentName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.studentName||'Candidate')}</strong><span class="mt-1 block truncate text-xs text-neutral-500">${esc(a.sessionTitle)} · ${a.submittedAt?`Submitted ${a.score??0}%`:'In progress'}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join('')}</div>`:empty('No candidate activity','Attempts will appear here when students start an examination.')}</section><aside class="${card} p-5"><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">Operations queue</p><h3 class="mt-1 font-display text-lg font-extrabold">Needs attention</h3><div class="mt-4 grid gap-3">${alertMarkup(`${sessions.filter(s=>s.status==='draft').length} draft exam(s) are not visible to candidates.`,'warning')}${alertMarkup(`${attempts.filter(a=>a.startedAt&&!a.submittedAt).length} candidate attempt(s) are still active.`,'info')}${alertMarkup(`${Store.listWhatsAppGroups().length} class WhatsApp group(s) have QR access configured.`,'success')}</div></aside></div>`;}

  function directoryPage(kind){const isStudents=kind==='students';const q=String(params().get('q')||'').trim().toLowerCase();const role=params().get('role')||'all';let users=Store.listUsers().filter(u=>isStudents?u.role==='student':['teacher','administrator'].includes(u.role));if(!isStudents&&role!=='all')users=users.filter(u=>u.role===role);users=users.filter(u=>!q||`${u.fullName} ${u.id}`.toLowerCase().includes(q));const rows=users.map(u=>{const cls=classFor(u.classId),ats=attemptsForUser(u);return`<tr class="hover:bg-neutral-50"><td class="px-4 py-3"><button class="flex items-center gap-3 text-left" data-user-detail="${esc(u.id)}"><span class="grid size-9 place-items-center rounded-lg bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span><strong class="block">${esc(u.fullName)}</strong><span class="text-xs text-neutral-500">${esc(u.id)}</span></span></button></td><td class="px-4 py-3 capitalize">${esc(u.role)}</td><td class="px-4 py-3">${esc(cls?.name||'—')}</td><td class="px-4 py-3">${ats.length}</td><td class="px-4 py-3">${badge(u.status)}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-user-detail="${esc(u.id)}" aria-label="Open ${esc(u.fullName)}">${icon('more')}</button></td></tr>`}).join('');const cards=users.map(u=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-user-detail="${esc(u.id)}"><span class="grid size-10 shrink-0 place-items-center rounded-xl bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(u.fullName)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(classFor(u.classId)?.name||u.role)}</span></span>${badge(u.status)}</button>`).join('');const filters=!isStudents?`<div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','teacher','administrator'].map(item=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${role===item?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}" data-staff-role="${item}">${item==='all'?'All staff':item}</button>`).join('')}</div>`:'';root().innerHTML=`${pageHead('Directory',isStudents?'Students':'Staff',isStudents?'Student records connect directly to class membership, exam history and integrity activity.':'Teacher and administrator records are kept separate from the student directory.',`<button class="${btnPrimary}" data-user-create data-default-role="${isStudents?'student':'teacher'}">Add ${isStudents?'student':'staff'}</button>`)}<div class="mb-4 grid gap-3 md:grid-cols-[minmax(0,1fr)_auto]"><label class="relative"><span class="sr-only">Search ${isStudents?'students':'staff'}</span><span class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-neutral-400">${icon('search','size-4')}</span><input id="user-search" class="${field} pl-9" value="${esc(params().get('q')||'')}" placeholder="Search name or ID"></label>${filters}</div><section class="${card} overflow-hidden">${users.length?responsiveTable(['User','Role','Class','Exam attempts','Status',''],rows,cards):empty(`No matching ${isStudents?'students':'staff'}`,'Change the current search or filter.')}</section>`;}

  function examTableRows(sessions){const rows=sessions.map(s=>{const ats=Store.attemptsForSession(s.id),submitted=ats.filter(a=>a.submittedAt&&!a.rewriteArchivedAt);return`<tr class="hover:bg-neutral-50"><td class="px-4 py-3"><button class="text-left" data-exam-detail="${esc(s.id)}"><strong class="block max-w-sm">${esc(s.title)}</strong><span class="mt-1 block font-mono text-[11px] tracking-wider text-neutral-500">${esc(s.id)}</span></button></td><td class="px-4 py-3"><span class="block text-xs font-semibold">${esc(s.classLevel)} · ${esc(s.classGroup)}</span><span class="mt-1 block max-w-xs text-xs text-neutral-500">${esc(coverage(s))}</span></td><td class="px-4 py-3"><strong>${s.questionCount}</strong><span class="block text-xs text-neutral-500">${esc(Store.durationLabel(s.durationSeconds))}</span></td><td class="px-4 py-3"><strong>${ats.length}</strong><span class="block text-xs text-neutral-500">${submitted.length} submitted</span></td><td class="px-4 py-3">${badge(sessionState(s))}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-exam-detail="${esc(s.id)}" aria-label="Manage ${esc(s.title)}">${icon('more')}</button></td></tr>`}).join('');const cards=sessions.map(s=>{const ats=Store.attemptsForSession(s.id);return`<button class="w-full p-4 text-left hover:bg-neutral-50" data-exam-detail="${esc(s.id)}"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><strong class="block truncate text-sm">${esc(s.title)}</strong><span class="mt-1 block font-mono text-[11px] tracking-wider text-neutral-500">${esc(s.id)}</span></div>${badge(sessionState(s))}</div><div class="mt-3 grid grid-cols-3 gap-2 text-xs text-neutral-600"><span>${s.questionCount} Q</span><span>${esc(Store.durationLabel(s.durationSeconds))}</span><span>${ats.length} attempts</span></div></button>`}).join('');return responsiveTable(['Exam','Audience','Paper','Attempts','Status',''],rows,cards);}
  function examsPage(){const status=['all','open','scheduled','draft','closed'].includes(params().get('status'))?params().get('status'):'all';const all=Store.listSessions(),sessions=status==='all'?all:all.filter(s=>sessionState(s)===status),ats=Store.getAttempts();root().innerHTML=`${pageHead('Assessment operations','Examinations','Create, distribute, update and audit examinations without exposing raw candidate URLs.',`<button class="${btnPrimary}" data-open-exam-wizard>Create exam</button>`)}<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Sessions',all.length,'all configured examinations')}${metric('Live',all.filter(s=>sessionState(s)==='open').length,'currently open')}${metric('Submitted',ats.filter(a=>a.submittedAt&&!a.rewriteArchivedAt).length,'current submitted attempts')}${metric('Integrity events',ats.reduce((n,a)=>n+(a.integrityEvents?.length||0),0),'attached to exam attempts')}</section><section class="${card} mt-5 overflow-hidden"><div class="flex flex-col gap-3 border-b border-neutral-200 p-4 sm:flex-row sm:items-center sm:justify-between"><div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','open','scheduled','draft','closed'].map(item=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${status===item?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}" data-exam-status="${item}">${item}</button>`).join('')}</div><span class="text-xs font-semibold text-neutral-500">${sessions.length} shown</span></div>${sessions.length?examTableRows(sessions):empty('No exams in this view','Change the filter or create a new examination.')}</section>`;}

  function classesPage(){const classes=Store.listClasses(),users=Store.listUsers(),groups=Store.listWhatsAppGroups();root().innerHTML=`${pageHead('Academic structure','Classes & communication','Manage class groups and attach one parent/student WhatsApp group to the intended class.',`<button class="${btnPrimary}" data-class-create>New class</button><button class="${btnSecondary}" data-whatsapp-create>Add WhatsApp group</button>`)}<div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3">${classes.filter(c=>c.status==='active').map(cls=>{const students=users.filter(u=>u.role==='student'&&u.classId===cls.id),group=groups.find(g=>g.classId===cls.id);return`<article class="${card} p-5"><div class="flex items-start justify-between gap-3"><div><span class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">${esc(cls.classLevel)} · ${esc(cls.stream)}</span><h3 class="mt-2 font-display text-lg font-extrabold">${esc(cls.name)}</h3><p class="mt-1 text-xs text-neutral-500">${esc(cls.room||'Room not assigned')}</p></div><button class="${iconBtn}" data-class-detail="${esc(cls.id)}" aria-label="Manage ${esc(cls.name)}">${icon('more')}</button></div><div class="mt-4 grid grid-cols-2 gap-2"><div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">Students</span><strong class="mt-1 block">${students.length}/${cls.capacity}</strong></div><div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">WhatsApp</span><strong class="mt-1 block text-sm">${group?'Connected':'Not set'}</strong></div></div>${group?`<button class="mt-4 flex w-full items-center gap-2 rounded-xl border border-neutral-200 p-3 text-left text-xs font-semibold hover:bg-neutral-50" data-whatsapp-edit="${esc(group.id)}">${esc(group.name)}</button>`:''}</article>`}).join('')}</div><section class="${card} mt-6 overflow-hidden"><div class="flex items-center justify-between border-b border-neutral-200 p-5"><div><p class="text-xs font-bold uppercase tracking-[.12em] text-neutral-500">WhatsApp group management</p><h3 class="mt-1 font-display text-lg font-extrabold">Class group QR board</h3></div><button class="${btnSecondary}" data-whatsapp-create>Add group</button></div>${groups.length?responsiveTable(['Group','Class','Updated',''],groups.map(g=>`<tr><td class="px-4 py-3"><strong>${esc(g.name)}</strong></td><td class="px-4 py-3">${esc(classFor(g.classId)?.name||'Unassigned')}</td><td class="px-4 py-3 text-xs text-neutral-500">${esc(formatDate(g.updatedAt))}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-whatsapp-edit="${esc(g.id)}">QR</button></td></tr>`).join(''),groups.map(g=>`<button class="flex w-full items-center gap-3 p-4 text-left" data-whatsapp-edit="${esc(g.id)}"><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(g.name)}</strong><span class="text-xs text-neutral-500">${esc(classFor(g.classId)?.name||'Unassigned')}</span></span><span class="text-xs font-semibold">QR</span></button>`).join('')):empty('No WhatsApp groups yet','Add a group invite link and associate it with a class; Festacol will generate the QR locally.')}</section>`;}

  function questionsPage(){const subject=params().get('subject')||'all',type=params().get('type')||'all';const questions=data.questions.filter(q=>(subject==='all'||q.subjectCode===subject)&&(type==='all'||q.type===type));const rows=questions.slice(0,120).map(q=>`<tr class="hover:bg-neutral-50"><td class="max-w-xl px-4 py-3"><button class="text-left" data-question-detail="${q.id}"><strong class="line-clamp-2">${esc(q.prompt)}</strong><span class="mt-1 block text-xs text-neutral-500">#${q.id}${q.custom?' · Custom':''}</span></button></td><td class="px-4 py-3">${esc(q.subject)}</td><td class="px-4 py-3">${q.levels.map(x=>badge(x,'neutral')).join(' ')}</td><td class="px-4 py-3">${badge(q.type,'neutral')}</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-question-detail="${q.id}">${icon('more')}</button></td></tr>`).join('');const cards=questions.slice(0,120).map(q=>`<button class="w-full p-4 text-left" data-question-detail="${q.id}"><strong class="line-clamp-2 text-sm">${esc(q.prompt)}</strong><span class="mt-2 flex items-center gap-2 text-xs text-neutral-500">${esc(q.subject)} ${badge(q.type,'neutral')}</span></button>`).join('');root().innerHTML=`${pageHead('Question intelligence','Question Bank','Review curriculum questions and locally authored items used by the examination engine.',`<button class="${btnPrimary}" data-question-create>Add question</button>`)}<div class="mb-4 grid gap-3 sm:grid-cols-2"><select id="question-subject-filter" class="${field}"><option value="all">All subjects</option>${data.subjectCatalog.map(s=>`<option value="${esc(s.code)}" ${subject===s.code?'selected':''}>${esc(s.label)}</option>`).join('')}</select><div class="flex overflow-x-auto rounded-lg border border-neutral-300 bg-white p-1">${['all','single','multi','boolean','fill','fill-multi'].map(x=>`<button class="min-h-9 whitespace-nowrap rounded-md px-3 text-xs font-semibold ${type===x?'bg-black text-white':'hover:bg-neutral-100'}" data-question-type="${x}">${x}</button>`).join('')}</div></div><section class="${card} overflow-hidden">${questions.length?responsiveTable(['Question','Subject','Levels','Type',''],rows,cards):empty('No matching questions','Change the current filters or add a custom question.')}</section>`;}

  function reportsPage(){const view=['overview','exams','students','placements','integrity'].includes(params().get('view'))?params().get('view'):'overview';const tabs=[['overview','Overview'],['exams','Exams'],['students','Students'],['placements','Placements'],['integrity','Integrity']],submitted=Store.getAttempts().filter(a=>a.submittedAt);let content='';if(view==='overview')content=`<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">${metric('Submissions',submitted.filter(a=>!a.rewriteArchivedAt).length,'current completed attempts')}${metric('Average',`${mean(submitted.filter(a=>!a.rewriteArchivedAt).map(a=>a.score))}%`,'current attempt average')}${metric('Integrity',`${mean(submitted.filter(a=>!a.rewriteArchivedAt).map(a=>a.integrityScore??100))}%`,'browser signal score')}${metric('Previous attempts',submitted.filter(a=>a.rewriteArchivedAt).length,'preserved rewrite history')}</section>`;if(view==='exams')content=`<section class="${card} overflow-hidden">${examTableRows(Store.listSessions())}</section>`;if(view==='students'){const students=Store.listUsers().filter(u=>u.role==='student');content=`<section class="${card} overflow-hidden">${responsiveTable(['Student','Attempts','Average','Integrity',''],students.map(u=>{const rows=attemptsForUser(u).filter(a=>a.submittedAt&&!a.rewriteArchivedAt);return`<tr><td class="px-4 py-3"><button class="font-semibold" data-user-detail="${esc(u.id)}">${esc(u.fullName)}</button></td><td class="px-4 py-3">${rows.length}</td><td class="px-4 py-3">${mean(rows.map(a=>a.score))}%</td><td class="px-4 py-3">${mean(rows.map(a=>a.integrityScore??100))}%</td><td class="px-4 py-3 text-right"><button class="${iconBtn}" data-user-detail="${esc(u.id)}">${icon('more')}</button></td></tr>`}).join(''),students.map(u=>`<button class="flex w-full items-center gap-3 p-4 text-left" data-user-detail="${esc(u.id)}"><span class="grid size-10 place-items-center rounded-xl bg-neutral-100 text-xs font-bold">${esc(initials(u.fullName))}</span><span class="flex-1"><strong class="text-sm">${esc(u.fullName)}</strong><span class="block text-xs text-neutral-500">${attemptsForUser(u).length} attempt records</span></span></button>`).join(''))}</section>`;}if(view==='placements')content=`<section class="${card} p-5"><h3 class="font-display text-lg font-extrabold">Qualifier placements</h3><div class="mt-4 grid gap-3">${submitted.filter(a=>a.placement&&!a.rewriteArchivedAt).map(a=>`<button class="flex items-center gap-3 rounded-xl border border-neutral-200 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="flex-1"><strong class="block text-sm">${esc(a.studentName)}</strong><span class="text-xs text-neutral-500">${esc(a.sessionTitle)}</span></span>${badge(a.placement.assignedTrack,'neutral')}<strong class="text-sm">${a.placement.confidence}%</strong></button>`).join('')||'<p class="text-sm text-neutral-500">No qualifier results yet.</p>'}</div></section>`;if(view==='integrity'){const events=submitted.flatMap(a=>(a.integrityEvents||[]).map(ev=>({attempt:a,event:ev}))).sort((a,b)=>b.event.at-a.event.at);content=`<section class="${card} overflow-hidden"><div class="border-b border-neutral-200 p-5"><h3 class="font-display text-lg font-extrabold">Integrity event log</h3><p class="mt-1 text-xs text-neutral-500">Every event remains linked to the exact student attempt and examination.</p></div><div class="divide-y divide-neutral-100">${events.map(({attempt:a,event:ev})=>`<button class="flex w-full items-start gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="mt-1 size-2 shrink-0 rounded-full bg-amber-500"></span><span class="min-w-0 flex-1"><strong class="block text-sm">${esc(a.studentName)} · ${esc(ev.type)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(a.sessionTitle)} · ${esc(formatDate(ev.at))}</span></span></button>`).join('')||'<p class="p-5 text-sm text-neutral-500">No integrity events recorded.</p>'}</div></section>`;}root().innerHTML=`${pageHead('Academic intelligence','Reports','Exam, student, placement and integrity records share the same attempt relationships.')}<nav class="mb-5 flex overflow-x-auto rounded-xl border border-neutral-200 bg-white p-1" aria-label="Report views">${tabs.map(([key,name])=>`<a href="${href('reports',{view:key})}" data-admin-link class="min-h-9 whitespace-nowrap rounded-lg px-3 py-2 text-xs font-semibold ${view===key?'bg-black text-white':'text-neutral-600 hover:bg-neutral-100'}">${name}</a>`).join('')}</nav>${content}`;}

  function settingsPage(){root().innerHTML=`${pageHead('Workspace','Settings','Manage browser-local prototype records. Production authentication, authorization and durable storage still require a backend.')}<section class="${card} overflow-hidden"><div class="border-b border-neutral-200 p-5"><h3 class="font-display text-lg font-extrabold">Local data</h3></div><div class="divide-y divide-neutral-100">${[['Exam sessions',Store.listSessions().length,'sessions'],['Candidate attempts',Store.getAttempts().length,'attempts'],['WhatsApp groups',Store.listWhatsAppGroups().length,'groups'],['Custom questions',Store.listCustomQuestions().length,'questions']].map(([name,count,key])=>`<div class="flex items-center justify-between gap-4 p-4"><div><strong class="text-sm">${name}</strong><p class="mt-1 text-xs text-neutral-500">${count} stored</p></div><button class="${btnSecondary}" data-clear-local="${key}">Clear</button></div>`).join('')}<div class="flex items-center justify-between gap-4 p-4"><div><strong class="text-sm text-red-700">Reset entire prototype</strong><p class="mt-1 text-xs text-neutral-500">Sessions, attempts, users, classes, groups and local question changes.</p></div><button class="${btnDanger}" data-reset-all>Reset all</button></div></div></section>`;}

  function userDetail(userId){const user=Store.listUsers().find(u=>u.id===userId);if(!user){invalidOverlay('User record not found.');return;}const attempts=attemptsForUser(user).sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)),done=attempts.filter(a=>a.submittedAt&&!a.rewriteArchivedAt);openDialog(`${modalHeader(user.role==='student'?'Student record':'Staff record',user.fullName,`${user.id} · ${classFor(user.classId)?.name||user.role}`)}<div class="p-5 sm:p-6"><div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Status',user.status],['Attempts',attempts.length],['Average',done.length?`${mean(done.map(a=>a.score))}%`:'—'],['Integrity',done.length?`${mean(done.map(a=>a.integrityScore??100))}%`:'—']].map(([k,v])=>`<div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div><div class="mt-6 flex flex-wrap gap-2"><button class="${btnSecondary}" data-user-edit="${esc(user.id)}">Edit user</button><button class="${btnSecondary}" data-user-toggle="${esc(user.id)}" data-next-status="${user.status==='active'?'inactive':'active'}">${user.status==='active'?'Suspend':'Activate'}</button></div>${user.role==='student'?`<div class="mt-6"><div class="flex items-center justify-between"><h3 class="font-display text-lg font-extrabold">Exam history</h3><span class="text-xs text-neutral-500">Exact studentHash relationship</span></div><div class="mt-3 divide-y divide-neutral-100 rounded-xl border border-neutral-200">${attempts.length?attempts.map(a=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.sessionTitle)}</strong><span class="mt-1 block text-xs text-neutral-500">${a.submittedAt?`${a.score??0}% · Integrity ${a.integrityScore??100}%`:'In progress'}${a.rewriteArchivedAt?' · Previous attempt':''}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join(''):'<p class="p-4 text-sm text-neutral-500">No exam activity for this identity.</p>'}</div></div>`:''}</div>`);}

  function attemptDetail(attemptHash){const attempt=Store.getAttempts().find(a=>a.attemptHash===attemptHash);if(!attempt){invalidOverlay('Attempt record not found.');return;}const session=Store.findSessionById(attempt.sessionId),events=attempt.integrityEvents||[];openDialog(`${modalHeader('Attempt audit',attempt.studentName||'Candidate',`${attempt.sessionTitle} · ${attempt.sessionId}`)}<div class="p-5 sm:p-6"><div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Status',attempt.rewriteArchivedAt?'Previous':attempt.submittedAt?'Submitted':'In progress'],['Score',attempt.submittedAt?`${attempt.score??0}%`:'—'],['Integrity',`${attempt.integrityScore??100}%`],['Events',events.length]].map(([k,v])=>`<div class="rounded-xl bg-neutral-50 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div>${attempt.rewriteArchivedAt?`<div class="mt-4">${alertMarkup('This is a preserved previous submission. A rewrite was authorized without deleting the original score or proctor log.','info')}</div>`:''}<section class="mt-6"><h3 class="font-display text-lg font-extrabold">Integrity / proctor log</h3><div class="mt-3 max-h-72 divide-y divide-neutral-100 overflow-y-auto rounded-xl border border-neutral-200">${events.length?events.map(ev=>`<div class="flex items-start gap-3 p-3"><span class="mt-1 size-2 shrink-0 rounded-full bg-amber-500"></span><div><strong class="text-sm">${esc(ev.type)}</strong><p class="mt-1 text-xs text-neutral-500">${esc(formatDate(ev.at))}${ev.seconds?` · ${Number(ev.seconds).toFixed(1)} sec`:''}</p></div></div>`).join(''):'<p class="p-4 text-sm text-neutral-500">No integrity exceptions recorded for this attempt.</p>'}</div></section><div class="mt-6 flex flex-wrap gap-2">${!attempt.submittedAt?`<button class="${btnDanger}" data-reset-unfinished data-session-id="${esc(attempt.sessionId)}" data-candidate-hash="${esc(attempt.candidateHash)}">Reset unfinished attempt</button>`:!attempt.rewriteArchivedAt?`<button class="${btnDanger}" data-authorize-rewrite data-session-id="${esc(attempt.sessionId)}" data-candidate-hash="${esc(attempt.candidateHash)}">Authorize rewrite</button>`:''}${session?`<button class="${btnSecondary}" data-exam-detail="${esc(session.id)}">Open exam</button>`:''}</div></div>`);}

  function examDetail(sessionId){const s=Store.findSessionById(sessionId);if(!s){invalidOverlay('Exam record not found.');return;}const attempts=Store.attemptsForSession(s.id).sort((a,b)=>(b.submittedAt||b.startedAt||0)-(a.submittedAt||a.startedAt||0)),activeAttempts=attempts.filter(a=>!a.rewriteArchivedAt),submitted=activeAttempts.filter(a=>a.submittedAt),link=directExamLink(s),camera=Proctor.getAdminPolicy(s.id).cameraRequired;openDialog(`${modalHeader('Exam management',s.title,`${s.classLevel} · ${s.classGroup} · ${Store.getModeLabel(s.mode)}`)}<div class="p-5 sm:p-6"><div class="grid gap-4 lg:grid-cols-[220px_minmax(0,1fr)]"><div><div class="rounded-2xl border border-neutral-200 bg-neutral-50 p-4"><div id="exam-detail-qr" class="mx-auto max-w-44 rounded-xl bg-white p-3"></div><p class="mt-3 text-center text-xs font-semibold text-neutral-500">Scan to open this exam</p></div></div><div class="grid content-start gap-3">${examIdLabel(s)}<div class="grid grid-cols-2 gap-3 sm:grid-cols-4">${[['Questions',s.questionCount],['Duration',Store.durationLabel(s.durationSeconds)],['Attempts',activeAttempts.length],['Camera',camera?'Required':'Off']].map(([k,v])=>`<div class="rounded-xl border border-neutral-200 p-3"><span class="text-xs text-neutral-500">${k}</span><strong class="mt-1 block text-sm">${esc(v)}</strong></div>`).join('')}</div><div class="flex flex-wrap gap-2"><button class="${btnPrimary}" data-exam-edit="${esc(s.id)}">Edit settings</button><button class="${btnSecondary}" data-exam-toggle="${esc(s.id)}" data-next-status="${s.status==='closed'?'open':'closed'}">${s.status==='closed'?'Reopen exam':'Close exam'}</button><button class="${btnSecondary}" data-exam-duplicate="${esc(s.id)}">Duplicate</button><button class="${btnDanger}" data-exam-delete="${esc(s.id)}">Delete</button></div></div></div><section class="mt-7"><div class="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-between"><div><h3 class="font-display text-lg font-extrabold">Students & attempts</h3><p class="mt-1 text-xs text-neutral-500">Scores and proctor logs are linked directly to this exam and the stored student identity.</p></div><span class="text-xs font-semibold text-neutral-500">${submitted.length} submitted · ${activeAttempts.filter(a=>!a.submittedAt).length} active · ${attempts.filter(a=>a.rewriteArchivedAt).length} previous</span></div><div class="mt-3 divide-y divide-neutral-100 rounded-xl border border-neutral-200">${attempts.length?attempts.map(a=>`<button class="flex w-full items-center gap-3 p-4 text-left hover:bg-neutral-50" data-attempt-detail="${esc(a.attemptHash)}"><span class="grid size-9 shrink-0 place-items-center rounded-lg bg-neutral-100 text-xs font-bold">${esc(initials(a.studentName))}</span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">${esc(a.studentName||'Candidate')}</strong><span class="mt-1 block text-xs text-neutral-500">${a.submittedAt?`Score ${a.score??0}% · Integrity ${a.integrityScore??100}% · ${(a.integrityEvents||[]).length} log event(s)`:`In progress · ${Math.ceil(a.remainingSeconds??0)} sec remaining`}${a.rewriteArchivedAt?' · Previous attempt':''}</span></span>${badge(a.rewriteArchivedAt?'previous':a.submittedAt?'submitted':'in progress',a.rewriteArchivedAt?'neutral':a.submittedAt?'emerald':'amber')}</button>`).join(''):'<p class="p-5 text-sm text-neutral-500">No candidate attempts yet.</p>'}</div></section></div>`);renderQr('#exam-detail-qr',link);}

  const availableQuestionCount=(draft)=>data.questions.filter(q=>q.levels?.includes(draft.classLevel)&&q.examModes?.includes(draft.mode)&&draft.subjects.includes(q.subjectCode)).length;
  const wizardSubjects=(draft)=>data.subjectCatalog.filter(s=>s.levels.includes(draft.classLevel)&&data.questions.some(q=>q.subjectCode===s.code&&q.levels.includes(draft.classLevel)&&q.examModes.includes(draft.mode)));
  const initWizard=()=>({mode:'qualifier',classLevel:'SS1',classGroup:'Qualifier',subjects:['q-eng','q-math','q-bst','q-social'],placementTracks:[...Store.TRACKS],durationSeconds:1800,questionCount:10,status:'open',title:'',instructions:'',integrityPolicy:{focusMonitoring:true,fullscreenPrompt:true,clipboardGuard:true,warnAfter:2},cameraRequired:false});
  function examWizard(step=1){if(!wizard)wizard=initWizard();step=Math.min(5,Math.max(1,Number(step)||1));if(wizard.mode==='qualifier'){wizard.classLevel='SS1';wizard.classGroup='Qualifier';}if(wizard.mode==='waec')wizard.classLevel='SS3';const available=availableQuestionCount(wizard);wizard.questionCount=Math.min(150,Math.max(5,wizard.questionCount));const steps=['Scope','Coverage','Paper','Integrity','Review'];let body='';if(step===1)body=`<div class="grid gap-5"><div><p class="${label}">Exam type</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${Object.entries(MODES).map(([key,name])=>`<button type="button" class="rounded-xl border p-4 text-left transition ${wizard.mode===key?'border-black bg-black text-white':'border-neutral-200 hover:bg-neutral-50'}" data-wizard-mode="${key}"><strong class="block text-sm">${name}</strong></button>`).join('')}</div></div><div><p class="${label}">Class level</p><div class="mt-2 grid grid-cols-3 gap-2">${['SS1','SS2','SS3'].map(x=>`<button class="${wizard.classLevel===x?'bg-black text-white':'border border-neutral-300 bg-white text-neutral-800'} min-h-10 rounded-lg text-sm font-semibold disabled:opacity-30" data-wizard-level="${x}" ${wizard.mode==='qualifier'&&x!=='SS1'||wizard.mode==='waec'&&x!=='SS3'?'disabled':''}>${x}</button>`).join('')}</div></div><div><p class="${label}">Class group</p><div class="mt-2 flex flex-wrap gap-2">${['Qualifier','Science','Arts','Social Science','General'].map(x=>`<button class="min-h-10 rounded-lg border px-3 text-sm font-semibold ${wizard.classGroup===x?'border-black bg-black text-white':'border-neutral-300 bg-white'}" data-wizard-group="${esc(x)}">${esc(x)}</button>`).join('')}</div></div></div>`;if(step===2)body=`<div class="grid gap-5">${wizard.mode==='qualifier'?`<div><p class="${label}">Eligible placement tracks</p><div class="mt-2 grid gap-2 sm:grid-cols-3">${Store.TRACKS.map(x=>`<button class="rounded-xl border p-4 text-left ${wizard.placementTracks.includes(x)?'border-black bg-neutral-100':'border-neutral-200'}" data-wizard-track="${esc(x)}"><strong class="text-sm">${esc(x)}</strong></button>`).join('')}</div></div>`:''}<div><p class="${label}">Subject coverage</p><div class="mt-2 grid gap-2 sm:grid-cols-2">${wizardSubjects(wizard).map(s=>`<button class="rounded-xl border p-4 text-left ${wizard.subjects.includes(s.code)?'border-black bg-neutral-100':'border-neutral-200'}" data-wizard-subject="${esc(s.code)}"><strong class="text-sm">${esc(s.label)}</strong><span class="mt-1 block text-xs text-neutral-500">${esc(s.code)}</span></button>`).join('')}</div></div></div>`;if(step===3)body=`<div class="grid gap-7"><div><div class="flex items-center justify-between gap-3"><label for="duration-range" class="${label}">Duration</label><strong id="duration-value" class="rounded-full bg-neutral-100 px-3 py-1 text-xs">${esc(Store.durationLabel(wizard.durationSeconds))}</strong></div><input id="duration-range" type="range" min="30" max="10800" step="30" value="${wizard.durationSeconds}" class="mt-4 h-2 w-full cursor-pointer appearance-none rounded-lg bg-neutral-200 accent-black"></div><div><div class="flex items-center justify-between gap-3"><label for="question-count-range" class="${label}">Total questions</label><strong id="question-count-value" class="rounded-full bg-neutral-100 px-3 py-1 text-xs">${wizard.questionCount}</strong></div><input id="question-count-range" type="range" min="5" max="150" step="1" value="${wizard.questionCount}" class="mt-4 h-2 w-full cursor-pointer appearance-none rounded-lg bg-neutral-200 accent-black"><p class="mt-2 text-xs ${available<wizard.questionCount?'font-semibold text-red-700':'text-neutral-500'}">${available} matching question(s) are currently available for this configuration.</p></div><label><span class="${label}">Candidate instruction</span><textarea id="wizard-instructions" class="${field} mt-2 min-h-24" maxlength="140">${esc(wizard.instructions)}</textarea></label></div>`;if(step===4)body=`<div class="grid gap-3">${[['focusMonitoring','Monitor tab/window changes'],['fullscreenPrompt','Prompt fullscreen'],['clipboardGuard','Block clipboard actions']].map(([key,name])=>`<label class="flex min-h-16 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><strong class="text-sm">${name}</strong><input data-integrity-policy="${key}" type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${wizard.integrityPolicy[key]?'checked':''}></label>`).join('')}<label class="flex min-h-20 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><span><strong class="block text-sm">Require candidate camera</strong><span class="mt-1 block text-xs text-neutral-500">Candidate must grant camera access before the exam can start or resume.</span></span><input data-proctor-camera type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${wizard.cameraRequired?'checked':''}></label><label><span class="${label}">Warn after integrity events</span><input id="warn-after" type="number" min="1" max="10" class="${field} mt-2" value="${wizard.integrityPolicy.warnAfter}"></label><div><p class="${label}">Initial status</p><div class="mt-2 grid grid-cols-3 gap-2">${['open','draft','closed'].map(x=>`<button class="min-h-10 rounded-lg border text-sm font-semibold ${wizard.status===x?'border-black bg-black text-white':'border-neutral-300'}" data-wizard-status="${x}">${x}</button>`).join('')}</div></div></div>`;if(step===5){const title=wizard.title||`${wizard.classLevel} ${wizard.mode==='qualifier'?'Placement Qualifier':'Assessment'}`;body=`<div class="grid gap-4"><label><span class="${label}">Exam title</span><input id="wizard-title" class="${field} mt-2" maxlength="72" value="${esc(title)}"></label><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Audience</span><strong class="mt-1 block text-sm">${esc(wizard.classLevel)} · ${esc(wizard.classGroup)}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Paper</span><strong class="mt-1 block text-sm">${wizard.questionCount} questions · ${esc(Store.durationLabel(wizard.durationSeconds))}</strong></div></div>${available<wizard.questionCount?alertMarkup('The selected paper is larger than the available matching question bank.','danger'):alertMarkup('The exam is ready to create. Distribution will expose only a QR code and Exam ID.','success')}</div>`;}openDialog(`${modalHeader('Exam builder','Create examination','Five focused steps: scope, coverage, paper, integrity and review.')}<div class="p-5 sm:p-6"><div class="grid grid-cols-5 gap-1">${steps.map((name,index)=>`<div class="min-w-0 text-center"><span class="mx-auto grid size-8 place-items-center rounded-full text-xs font-bold ${index+1<=step?'bg-black text-white':'bg-neutral-100 text-neutral-500'}">${index+1}</span><span class="mt-1 hidden truncate text-[10px] font-semibold text-neutral-500 sm:block">${name}</span></div>`).join('')}</div><div class="mt-6">${body}</div><div class="mt-7 flex items-center justify-between gap-3"><button class="${btnSecondary}" data-wizard-prev data-step="${step}" ${step===1?'disabled':''}>Back</button><button class="${btnPrimary}" data-wizard-next data-step="${step}" ${step===3&&available<5?'disabled':''}>${step===5?'Create exam':'Continue'}</button></div></div>`,'max-w-4xl');}
  function examCreated(session){const link=directExamLink(session);openDialog(`${modalHeader('Exam created','Distribution ready','No raw candidate URL is shown in the admin console.')}<div class="p-5 text-center sm:p-7"><div id="created-exam-qr" class="mx-auto max-w-52 rounded-2xl border border-neutral-200 bg-white p-4"></div><div class="mx-auto mt-5 max-w-sm">${examIdLabel(session)}</div><div class="mt-6 flex flex-col justify-center gap-2 sm:flex-row"><button class="${btnPrimary}" data-exam-detail="${esc(session.id)}">Manage exam</button><button class="${btnSecondary}" data-close-dialog>Done</button></div></div>`,'max-w-xl');renderQr('#created-exam-qr',link);}
  function examEdit(sessionId){const s=Store.findSessionById(sessionId);if(!s){toast('Exam not found.','danger');return;}const attempts=Store.attemptsForSession(s.id).filter(a=>!a.rewriteArchivedAt),structuralLocked=attempts.length>0,camera=Proctor.getAdminPolicy(s.id).cameraRequired;openDialog(`${modalHeader('Exam settings','Edit examination',structuralLocked?'Candidates have started this exam. Paper shape is locked; delivery and integrity settings remain editable.':'No candidate has started yet, so the paper shape can still be updated.')}<form id="exam-edit-form" data-session-id="${esc(s.id)}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Exam title</span><input id="exam-edit-title" class="${field} mt-2" value="${esc(s.title)}" maxlength="72"></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Duration (seconds)</span><input id="exam-edit-duration" type="number" min="30" max="10800" step="30" class="${field} mt-2" value="${s.durationSeconds}" ${structuralLocked?'disabled':''}></label><label><span class="${label}">Question count</span><input id="exam-edit-count" type="number" min="5" max="150" class="${field} mt-2" value="${s.questionCount}" ${structuralLocked?'disabled':''}></label></div><label><span class="${label}">Candidate instruction</span><textarea id="exam-edit-instructions" class="${field} mt-2 min-h-24" maxlength="140">${esc(s.instructions||'')}</textarea></label><div class="grid gap-3 sm:grid-cols-2"><label><span class="${label}">Status</span><select id="exam-edit-status" class="${field} mt-2">${['open','draft','closed'].map(x=>`<option value="${x}" ${s.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Warn after events</span><input id="exam-edit-warn" type="number" min="1" max="10" class="${field} mt-2" value="${s.integrityPolicy.warnAfter}"></label></div><label class="flex min-h-16 items-center justify-between gap-4 rounded-xl border border-neutral-200 p-4"><span><strong class="block text-sm">Require candidate camera</strong></span><input id="exam-edit-camera" type="checkbox" class="size-5 rounded border-neutral-300 text-black focus:ring-black" ${camera?'checked':''}></label><div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-end"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="submit" class="${btnPrimary}">Save settings</button></div></form>`);}

  function whatsappDialog(groupId=''){const existing=Store.listWhatsAppGroups().find(g=>g.id===groupId)||null,classes=Store.listClasses().filter(c=>c.status==='active');openDialog(`${modalHeader('Class communication',existing?'Manage WhatsApp group':'Add WhatsApp group','Paste a WhatsApp invite link, associate it with the intended class, and generate the QR locally.')}<form id="whatsapp-form" data-group-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Class</span><select id="whatsapp-class" class="${field} mt-2" required><option value="">Choose class</option>${classes.map(c=>`<option value="${esc(c.id)}" ${existing?.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label><span class="${label}">Group name</span><input id="whatsapp-name" class="${field} mt-2" maxlength="72" value="${esc(existing?.name||'')}" placeholder="SS1 Science Parents"></label><label><span class="${label}">WhatsApp group invite link</span><input id="whatsapp-link" type="url" class="${field} mt-2" value="${esc(existing?.inviteUrl||'')}" placeholder="https://chat.whatsapp.com/..." required></label><div id="whatsapp-error" class="hidden"></div>${existing?`<div class="rounded-2xl border border-neutral-200 bg-neutral-50 p-4"><div id="whatsapp-qr" class="mx-auto max-w-48 rounded-xl bg-white p-3"></div><p class="mt-2 text-center text-xs text-neutral-500">QR for ${esc(existing.name)}</p></div>`:''}<div class="flex flex-col-reverse gap-2 sm:flex-row sm:justify-between"><div>${existing?`<button type="button" class="${btnDanger}" data-whatsapp-delete="${esc(existing.id)}">Delete group</button>`:''}</div><div class="flex flex-col-reverse gap-2 sm:flex-row"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button type="submit" class="${btnPrimary}">${existing?'Save changes':'Save & generate QR'}</button></div></div></form>`,'max-w-2xl');if(existing)renderQr('#whatsapp-qr',existing.inviteUrl);}
  function classDialog(classId=''){const existing=Store.listClasses().find(c=>c.id===classId)||null;openDialog(`${modalHeader('Academic structure',existing?'Edit class':'Create class','Keep class naming and communication associations consistent.')}<form id="class-form" data-class-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Level</span><select id="class-level" class="${field} mt-2">${['SS1','SS2','SS3'].map(x=>`<option ${existing?.classLevel===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Stream</span><select id="class-stream" class="${field} mt-2">${['Qualifier','Science','Arts','Social Science','General'].map(x=>`<option ${existing?.stream===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Capacity</span><input id="class-capacity" type="number" min="1" max="500" class="${field} mt-2" value="${existing?.capacity||60}"></label><label><span class="${label}">Room</span><input id="class-room" class="${field} mt-2" value="${esc(existing?.room||'')}" placeholder="Science Wing"></label></div><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Save class</button></div></form>`,'max-w-2xl');}
  function classDetail(classId){const cls=Store.listClasses().find(c=>c.id===classId);if(!cls){invalidOverlay('Class record not found.');return;}const students=Store.listUsers().filter(u=>u.role==='student'&&u.classId===cls.id),group=Store.whatsAppGroupForClass(cls.id);openDialog(`${modalHeader('Class management',cls.name,`${students.length} students · capacity ${cls.capacity}`)}<div class="p-5 sm:p-6"><div class="grid gap-3 sm:grid-cols-2"><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Stream</span><strong class="mt-1 block">${esc(cls.stream)}</strong></div><div class="rounded-xl bg-neutral-50 p-4"><span class="text-xs text-neutral-500">Room</span><strong class="mt-1 block">${esc(cls.room||'Not assigned')}</strong></div></div><div class="mt-5 flex flex-wrap gap-2"><button class="${btnPrimary}" data-class-edit="${esc(cls.id)}">Edit class</button><button class="${btnSecondary}" data-whatsapp-${group?'edit':'for-class'}="${esc(group?.id||cls.id)}">${group?'Manage WhatsApp':'Add WhatsApp group'}</button><button class="${btnDanger}" data-class-delete="${esc(cls.id)}">Delete class</button></div></div>`,'max-w-2xl');}

  function userForm(userId='',defaultRole=currentPage()==='staff'?'teacher':'student'){const existing=Store.listUsers().find(u=>u.id===userId)||null,classes=Store.listClasses().filter(c=>c.status==='active');openDialog(`${modalHeader('Directory',existing?'Edit user':`Add ${defaultRole==='student'?'student':'staff member'}`,'Student identities connect directly to exam history.')}<form id="user-form" data-user-id="${esc(existing?.id||'')}" class="grid gap-5 p-5 sm:p-6"><label><span class="${label}">Full name</span><input id="user-name" class="${field} mt-2" value="${esc(existing?.fullName||'')}" required></label><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Role</span><select id="user-role" class="${field} mt-2">${['student','teacher','administrator'].map(x=>`<option ${existing?.role===x||!existing&&defaultRole===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span class="${label}">Class</span><select id="user-class" class="${field} mt-2"><option value="">No class</option>${classes.map(c=>`<option value="${esc(c.id)}" ${existing?.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label></div><label><span class="${label}">Guardian</span><input id="user-guardian" class="${field} mt-2" value="${esc(existing?.guardian||'')}"></label><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Save user</button></div></form>`,'max-w-2xl');}
  function questionDetail(id){const q=data.questions.find(item=>item.id===Number(id));if(!q){invalidOverlay('Question record not found.');return;}openDialog(`${modalHeader('Question bank',`Question ${q.id}`,`${q.subject} · ${q.type}`)}<div class="p-5 sm:p-6"><div class="rounded-xl border border-neutral-200 bg-neutral-50 p-5"><p class="font-semibold leading-7">${esc(q.prompt)}</p>${q.options?`<div class="mt-4 grid gap-2">${q.options.map((option,index)=>`<div class="flex gap-3 rounded-lg border border-neutral-200 bg-white p-3"><span class="grid size-7 shrink-0 place-items-center rounded-md bg-black text-xs font-bold text-white">${String.fromCharCode(65+index)}</span><span class="text-sm text-neutral-700">${esc(option)}</span></div>`).join('')}</div>`:''}</div>${q.custom?`<div class="mt-5 flex gap-2"><button class="${btnDanger}" data-question-delete="${q.id}">Delete custom question</button></div>`:''}</div>`,'max-w-2xl');}
  function questionForm(){openDialog(`${modalHeader('Question authoring','Add question','Create a scored local question with an explicit answer key.')}<form id="question-form" class="grid gap-5 p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-2"><label><span class="${label}">Subject</span><select id="question-subject" class="${field} mt-2">${data.subjectCatalog.map(s=>`<option value="${esc(s.code)}">${esc(s.label)}</option>`).join('')}</select></label><label><span class="${label}">Type</span><select id="question-kind" class="${field} mt-2"><option value="single">Single choice</option><option value="boolean">True / False</option><option value="fill">Fill</option></select></label></div><label><span class="${label}">Question</span><textarea id="question-prompt" class="${field} mt-2 min-h-28" required></textarea></label><div id="question-answer-fields">${questionAnswerFields('single')}</div><label><span class="${label}">Class level</span><select id="question-level" class="${field} mt-2"><option>SS1</option><option selected>SS2</option><option>SS3</option></select></label><div class="flex justify-end gap-2"><button type="button" class="${btnSecondary}" data-close-dialog>Cancel</button><button class="${btnPrimary}" type="submit">Add question</button></div></form>`,'max-w-2xl');}
  function questionAnswerFields(type){if(type==='boolean')return`<label><span class="${label}">Correct answer</span><select id="question-boolean-answer" class="${field} mt-2"><option value="true">True</option><option value="false">False</option></select></label>`;if(type==='fill')return`<label><span class="${label}">Accepted answer</span><input id="question-fill-answer" class="${field} mt-2" required placeholder="Accepted response"></label>`;return`<div class="grid gap-3"><div id="question-options" class="grid gap-2 sm:grid-cols-2">${['A','B','C','D'].map(x=>`<input class="${field}" data-option-input placeholder="${x}. Option">`).join('')}</div><label><span class="${label}">Correct option</span><select id="question-correct-option" class="${field} mt-2"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></label></div>`;}

  function invalidOverlay(message){hideDialogOnly();const changes={};for(const key of OVERLAY_KEYS)changes[key]=null;patchUrl(changes,{replace:true,renderNow:false});toast(message,'danger');}
  function renderOverlay(){const modal=params().get('modal');if(!modal){hideDialogOnly();return;}if(modal==='create-exam'){const step=Number(params().get('step')||1);examWizard(step);return;}if(modal==='exam-created'){const session=Store.findSessionById(params().get('exam'));if(!session){invalidOverlay('Exam not found.');return;}examCreated(session);return;}if(modal==='student'){userDetail(params().get('student'));return;}if(modal==='staff'){userDetail(params().get('staff'));return;}if(modal==='exam'){examDetail(params().get('exam'));return;}if(modal==='class'){classDetail(params().get('class'));return;}if(modal==='question'){questionDetail(params().get('question'));return;}if(modal==='attempt'){attemptDetail(params().get('attempt'));return;}hideDialogOnly();}

  async function render(){normalizeLocation();const host=document.getElementById('admin-alert');host.className='hidden';host.innerHTML='';const page=currentPage();chrome(page);await hydrateUserHashes();const renderer={overview:overviewPage,students:()=>directoryPage('students'),staff:()=>directoryPage('staff'),exams:examsPage,classes:classesPage,questions:questionsPage,reports:reportsPage,settings:settingsPage}[page];renderer();root().focus({preventScroll:true});renderOverlay();window.initFlowbite?.();}
  function validateWizardStep(step){if(step===2){if((wizard.mode==='single'||wizard.mode==='waec')&&wizard.subjects.length!==1)throw new Error('Choose one subject.');if(wizard.mode==='mixed'&&wizard.subjects.length<2)throw new Error('Choose at least two subjects.');if(wizard.mode==='qualifier'&&!wizard.subjects.length)throw new Error('Choose qualifier subjects.');if(wizard.mode==='qualifier'&&!wizard.placementTracks.length)throw new Error('Choose at least one placement track.');}if(step===3){const available=availableQuestionCount(wizard);if(available<5)throw new Error('At least five matching questions are required.');if(wizard.questionCount>available)throw new Error(`Only ${available} matching questions are available. Reduce the total question count before continuing.`);}}

  document.addEventListener('click',async(event)=>{
    const route=event.target.closest('[data-admin-route]');if(route){event.preventDefault();hideMobileNav();navigate(route.dataset.adminRoute);return;}
    const internal=event.target.closest('[data-admin-link]');if(internal){event.preventDefault();const url=new URL(internal.href);history.pushState({},'',url.href);render();return;}
    if(event.target.closest('#mobile-nav-button')){showMobileNav();return;}if(event.target.closest('[data-close-mobile-nav]')){hideMobileNav();return;}
    if(event.target.closest('[data-close-dialog]')){closeDialog();return;}if(event.target.closest('[data-toast-close]')){event.target.closest('.pointer-events-auto')?.remove();return;}
    if(event.target.closest('#admin-quick-create')||event.target.closest('[data-open-exam-wizard]')){wizard=initWizard();patchUrl({page:'exams',modal:'create-exam',step:1,...Object.fromEntries(RECORD_KEYS.map(k=>[k,null]))});return;}
    const staffRole=event.target.closest('[data-staff-role]');if(staffRole){navigate('staff',{role:staffRole.dataset.staffRole,q:params().get('q')||''});return;}
    const examStatus=event.target.closest('[data-exam-status]');if(examStatus){navigate('exams',{status:examStatus.dataset.examStatus});return;}
    const qType=event.target.closest('[data-question-type]');if(qType){navigate('questions',{subject:params().get('subject')||'all',type:qType.dataset.questionType});return;}
    const userDetailBtn=event.target.closest('[data-user-detail]');if(userDetailBtn){const user=Store.listUsers().find(u=>u.id===userDetailBtn.dataset.userDetail);openRecord(user?.role==='student'?'student':'staff',userDetailBtn.dataset.userDetail,user?.role==='student'?'students':'staff');return;}
    const examDetailBtn=event.target.closest('[data-exam-detail]');if(examDetailBtn){openRecord('exam',examDetailBtn.dataset.examDetail,'exams');return;}
    const classDetailBtn=event.target.closest('[data-class-detail]');if(classDetailBtn){openRecord('class',classDetailBtn.dataset.classDetail,'classes');return;}
    const questionDetailBtn=event.target.closest('[data-question-detail]');if(questionDetailBtn){openRecord('question',questionDetailBtn.dataset.questionDetail,'questions');return;}
    const attemptDetailBtn=event.target.closest('[data-attempt-detail]');if(attemptDetailBtn){openRecord('attempt',attemptDetailBtn.dataset.attemptDetail,currentPage());return;}
    const userCreate=event.target.closest('[data-user-create]');if(userCreate){userForm('',userCreate.dataset.defaultRole);return;}const userEdit=event.target.closest('[data-user-edit]');if(userEdit){userForm(userEdit.dataset.userEdit);return;}
    if(event.target.closest('[data-class-create]')){classDialog();return;}const classEdit=event.target.closest('[data-class-edit]');if(classEdit){classDialog(classEdit.dataset.classEdit);return;}
    if(event.target.closest('[data-question-create]')){questionForm();return;}
    if(event.target.closest('[data-whatsapp-create]')){whatsappDialog();return;}const waEdit=event.target.closest('[data-whatsapp-edit]');if(waEdit){whatsappDialog(waEdit.dataset.whatsappEdit);return;}const waForClass=event.target.closest('[data-whatsapp-for-class]');if(waForClass){whatsappDialog();queueMicrotask(()=>{document.getElementById('whatsapp-class').value=waForClass.dataset.whatsappForClass;});return;}
    const wizardMode=event.target.closest('[data-wizard-mode]');if(wizardMode){wizard.mode=wizardMode.dataset.wizardMode;wizard.subjects=[];if(wizard.mode==='qualifier'){wizard.classLevel='SS1';wizard.classGroup='Qualifier';wizard.subjects=['q-eng','q-math','q-bst','q-social'];wizard.placementTracks=[...Store.TRACKS];}if(wizard.mode==='waec')wizard.classLevel='SS3';examWizard(1);return;}
    const wizardLevel=event.target.closest('[data-wizard-level]');if(wizardLevel){wizard.classLevel=wizardLevel.dataset.wizardLevel;wizard.subjects=[];examWizard(1);return;}
    const wizardGroup=event.target.closest('[data-wizard-group]');if(wizardGroup){wizard.classGroup=wizardGroup.dataset.wizardGroup;examWizard(1);return;}
    const wizardTrack=event.target.closest('[data-wizard-track]');if(wizardTrack){const value=wizardTrack.dataset.wizardTrack;wizard.placementTracks=wizard.placementTracks.includes(value)?wizard.placementTracks.filter(x=>x!==value):[...wizard.placementTracks,value];examWizard(2);return;}
    const wizardSubject=event.target.closest('[data-wizard-subject]');if(wizardSubject){const value=wizardSubject.dataset.wizardSubject;if(['single','waec'].includes(wizard.mode))wizard.subjects=[value];else wizard.subjects=wizard.subjects.includes(value)?wizard.subjects.filter(x=>x!==value):[...wizard.subjects,value];examWizard(2);return;}
    const wizardStatus=event.target.closest('[data-wizard-status]');if(wizardStatus){wizard.status=wizardStatus.dataset.wizardStatus;examWizard(4);return;}
    if(event.target.closest('[data-wizard-prev]')){const step=Number(event.target.closest('[data-wizard-prev]').dataset.step)||1;if(step>1)patchUrl({modal:'create-exam',step:step-1},{replace:true});return;}
    const wizardNext=event.target.closest('[data-wizard-next]');if(wizardNext){const step=Number(wizardNext.dataset.step);try{validateWizardStep(step);if(step<5){if(step===4)wizard.integrityPolicy.warnAfter=Math.max(1,Math.min(10,Number(document.getElementById('warn-after')?.value)||2));patchUrl({modal:'create-exam',step:step+1},{replace:true});return;}wizard.title=document.getElementById('wizard-title')?.value.trim()||wizard.title||`${wizard.classLevel} Assessment`;const created=Store.saveSession({...wizard,placementTracks:wizard.placementTracks,integrityPolicy:wizard.integrityPolicy});Proctor.setAdminPolicy(created.id,{cameraRequired:wizard.cameraRequired});wizard=null;patchUrl({page:'exams',modal:'exam-created',step:null,exam:created.id},{replace:true});}catch(error){announce(error.message,'danger');}return;}
    const examEditBtn=event.target.closest('[data-exam-edit]');if(examEditBtn){examEdit(examEditBtn.dataset.examEdit);return;}
    const examToggle=event.target.closest('[data-exam-toggle]');if(examToggle){Store.updateSessionStatus(examToggle.dataset.examToggle,examToggle.dataset.nextStatus);toast('Exam status updated.','success');examDetail(examToggle.dataset.examToggle);examsPage();return;}
    const examDuplicate=event.target.closest('[data-exam-duplicate]');if(examDuplicate){const source=Store.findSessionById(examDuplicate.dataset.examDuplicate);if(source){const copy=Store.saveSession({...source,id:undefined,title:`${source.title} copy`.slice(0,72),status:'draft',createdAt:Date.now()});Proctor.setAdminPolicy(copy.id,Proctor.getAdminPolicy(source.id));toast('Exam duplicated as a draft.','success');openRecord('exam',copy.id,'exams');}return;}
    const examDelete=event.target.closest('[data-exam-delete]');if(examDelete){const id=examDelete.dataset.examDelete;confirmDialog({title:'Delete this examination?',detail:'The session definition will be removed. Existing attempt records remain available in reports for audit history.',confirm:'Delete exam',danger:true,onConfirm:async()=>{Store.deleteSession(id);toast('Exam deleted. Attempt history was preserved.','success');closeOverlayUrl({replace:true});}});return;}
    const reset=event.target.closest('[data-reset-unfinished]');if(reset){const {sessionId,candidateHash}=reset.dataset;confirmDialog({title:'Reset unfinished attempt?',detail:'The candidate can authenticate and start this same exam again.',confirm:'Reset attempt',danger:true,onConfirm:async()=>{Store.resetUnfinishedAttempt(sessionId,candidateHash);toast('Unfinished attempt reset.','success');openRecord('exam',sessionId,'exams');}});return;}
    const rewrite=event.target.closest('[data-authorize-rewrite]');if(rewrite){const {sessionId,candidateHash}=rewrite.dataset;confirmDialog({title:'Authorize a rewrite?',detail:'The submitted attempt, score and integrity log will be preserved as a previous attempt.',confirm:'Authorize rewrite',danger:true,onConfirm:async()=>{Store.authorizeRewrite(sessionId,candidateHash);toast('Rewrite authorized. Previous submission preserved.','success');openRecord('exam',sessionId,'exams');}});return;}
    const userToggle=event.target.closest('[data-user-toggle]');if(userToggle){Store.updateUserStatus(userToggle.dataset.userToggle,userToggle.dataset.nextStatus);toast('User status updated.','success');await render();return;}
    const classDelete=event.target.closest('[data-class-delete]');if(classDelete){const id=classDelete.dataset.classDelete;confirmDialog({title:'Delete this class?',detail:'Students remain in the directory, but the class and its associated WhatsApp group will be removed.',confirm:'Delete class',danger:true,onConfirm:async()=>{Store.deleteClass(id);toast('Class removed.','success');closeOverlayUrl({replace:true});}});return;}
    const waDelete=event.target.closest('[data-whatsapp-delete]');if(waDelete){const id=waDelete.dataset.whatsappDelete;confirmDialog({title:'Delete WhatsApp group mapping?',detail:'The invite link and QR mapping will be removed from this browser.',confirm:'Delete group',danger:true,onConfirm:async()=>{Store.deleteWhatsAppGroup(id);toast('WhatsApp group removed.','success');hideDialogOnly();await render();}});return;}
    const qDelete=event.target.closest('[data-question-delete]');if(qDelete){Store.deleteCustomQuestion(Number(qDelete.dataset.questionDelete));data=await Questions.load();closeOverlayUrl({replace:true});toast('Custom question deleted.','success');return;}
    const clear=event.target.closest('[data-clear-local]');if(clear){const key=clear.dataset.clearLocal;confirmDialog({title:`Clear ${key}?`,detail:'This affects only browser-local prototype data.',confirm:'Clear data',danger:true,onConfirm:async()=>{if(key==='sessions')Store.clearSessions();if(key==='attempts')Store.clearAttempts();if(key==='groups')Store.listWhatsAppGroups().forEach(g=>Store.deleteWhatsAppGroup(g.id));if(key==='questions')Store.listCustomQuestions().forEach(q=>Store.deleteCustomQuestion(q.id));data=await Questions.load();toast('Selected local data cleared.','success');await render();}});return;}
    if(event.target.closest('[data-reset-all]')){confirmDialog({title:'Reset the entire prototype?',detail:'All browser-local sessions, attempts, users, classes, groups and custom questions will be cleared.',confirm:'Reset prototype',danger:true,onConfirm:async()=>{Store.clearPrototypeData();data=await Questions.load();toast('Prototype data reset.','success');await render();}});return;}
  });

  document.addEventListener('change',(event)=>{if(event.target.id==='question-subject-filter')navigate('questions',{subject:event.target.value,type:params().get('type')||'all'});if(event.target.id==='question-kind'){const host=document.getElementById('question-answer-fields');if(host)host.innerHTML=questionAnswerFields(event.target.value);}const integrity=event.target.closest('[data-integrity-policy]');if(integrity&&wizard)wizard.integrityPolicy[integrity.dataset.integrityPolicy]=integrity.checked;if(event.target.matches('[data-proctor-camera]')&&wizard)wizard.cameraRequired=event.target.checked;});
  document.addEventListener('input',(event)=>{if(wizard){if(event.target.id==='duration-range'){wizard.durationSeconds=Number(event.target.value);document.getElementById('duration-value').textContent=Store.durationLabel(wizard.durationSeconds);}if(event.target.id==='question-count-range'){wizard.questionCount=Number(event.target.value);document.getElementById('question-count-value').textContent=String(wizard.questionCount);}if(event.target.id==='wizard-instructions')wizard.instructions=event.target.value;}});
  let searchTimer=null;document.addEventListener('input',(event)=>{if(event.target.id==='user-search'){clearTimeout(searchTimer);searchTimer=setTimeout(()=>navigate(currentPage(),{role:params().get('role')||'',q:event.target.value},true),220);}});

  document.addEventListener('submit',async(event)=>{
    if(event.target.id==='exam-edit-form'){event.preventDefault();const id=event.target.dataset.sessionId,s=Store.findSessionById(id),attempts=Store.attemptsForSession(id).filter(a=>!a.rewriteArchivedAt);if(!s)return;const available=availableQuestionCount(s);try{const requestedCount=attempts.length?s.questionCount:Number(document.getElementById('exam-edit-count').value);if(!attempts.length&&requestedCount>available)throw new Error(`Only ${available} matching questions are available for this exam.`);const updated=Store.saveSession({...s,title:document.getElementById('exam-edit-title').value,instructions:document.getElementById('exam-edit-instructions').value,status:document.getElementById('exam-edit-status').value,integrityPolicy:{...s.integrityPolicy,warnAfter:Number(document.getElementById('exam-edit-warn').value)},...(attempts.length?{}:{durationSeconds:Number(document.getElementById('exam-edit-duration').value),questionCount:requestedCount})});Proctor.setAdminPolicy(id,{cameraRequired:document.getElementById('exam-edit-camera').checked});toast('Exam settings updated.','success');examDetail(updated.id);examsPage();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='whatsapp-form'){event.preventDefault();const errorHost=document.getElementById('whatsapp-error');try{const saved=Store.saveWhatsAppGroup({id:event.target.dataset.groupId||undefined,classId:document.getElementById('whatsapp-class').value,name:document.getElementById('whatsapp-name').value,inviteUrl:document.getElementById('whatsapp-link').value});toast('WhatsApp group saved and QR generated.','success');whatsappDialog(saved.id);classesPage();}catch(error){errorHost.innerHTML=alertMarkup(error.message,'danger');errorHost.classList.remove('hidden');}return;}
    if(event.target.id==='class-form'){event.preventDefault();try{const level=document.getElementById('class-level').value,stream=document.getElementById('class-stream').value;Store.saveClass({id:event.target.dataset.classId||undefined,classLevel:level,stream,group:stream,name:`${level} ${stream}`,capacity:Number(document.getElementById('class-capacity').value),room:document.getElementById('class-room').value});hideDialogOnly();toast('Class saved.','success');await render();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='user-form'){event.preventDefault();try{const role=document.getElementById('user-role').value,classId=document.getElementById('user-class').value;if(role==='student'&&!classId)throw new Error('Choose a class for the student.');Store.saveUser({id:event.target.dataset.userId||undefined,fullName:document.getElementById('user-name').value,guardian:document.getElementById('user-guardian').value,role,classId});hideDialogOnly();toast('User saved.','success');await render();}catch(error){toast(error.message,'danger');}return;}
    if(event.target.id==='question-form'){event.preventDefault();try{const subjectCode=document.getElementById('question-subject').value,subject=Questions.subjectByCode(data,subjectCode),type=document.getElementById('question-kind').value,prompt=document.getElementById('question-prompt').value.trim(),level=document.getElementById('question-level').value;if(!prompt)throw new Error('Write the question stem.');const q={subject:subject?.label||subjectCode,subjectCode,domain:'Custom curriculum practice',label:'Custom question',prompt,type,levels:[level],pathways:['Science','Arts','Social Science'],examModes:['single','mixed','waec'],difficulty:'medium',explanation:'Teacher-authored local question.'};if(type==='single'){q.options=[...dialog().querySelectorAll('[data-option-input]')].map(input=>input.value.trim()).filter(Boolean);if(q.options.length<2)throw new Error('Add at least two answer options.');const answerIndex=Number(document.getElementById('question-correct-option').value);if(!q.options[answerIndex])throw new Error('Choose a correct option that has text.');q.answer=q.options[answerIndex];}if(type==='boolean')q.answer=document.getElementById('question-boolean-answer').value==='true';if(type==='fill'){const answer=document.getElementById('question-fill-answer').value.trim();if(!answer)throw new Error('Add an accepted answer.');q.acceptedAnswers=[answer];q.fillTemplate=[{text:`${prompt} `},{blank:'answer'}];}Store.saveCustomQuestion(q);data=await Questions.load();hideDialogOnly();toast('Question added.','success');await render();}catch(error){toast(error.message,'danger');}return;}
  });

  document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&!dialog()?.classList.contains('hidden'))closeDialog();else if(event.key==='Escape')hideMobileNav();});
  window.addEventListener('popstate',()=>render());
  document.addEventListener('keydown',(event)=>{if(event.target.id==='admin-global-search'&&event.key==='Enter')navigate('students',{q:event.target.value});});

  normalizeLocation();shell();
  dialog()?.addEventListener('click',(event)=>{if(event.target===dialog())closeDialog();});
  Questions.load().then(async(payload)=>{data=payload;await render();}).catch(error=>{root().innerHTML=`<section class="${card} mx-auto max-w-2xl p-7">${alertMarkup(error.message,'danger')}<h2 class="mt-5 font-display text-2xl font-extrabold">Question data unavailable</h2></section>`;announce(error.message,'danger');});
})();
